effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 base = texture2DCv(inputImg.texture, uv);
vec4 bloom = vec4(0.0);
float total = 0.0;
vec2 texSize = max(inputImg.size, vec2(1.0));
for (float x = -2.0; x <= 2.0; x++) {
for (float y = -2.0; y <= 2.0; y++) {
bloom += texture2DCv(inputImg.texture, uv + vec2(x, y) * radius / texSize);
total += 1.0;
}
}
bloom /= total;
gl_FragColor = mix(base, max(base, bloom), mix);
}
